import hmac
import hashlib
import json
import struct
import base64
import os
import re
from typing import Optional, Tuple, Dict, Any

# Secure session token handler for distributed cache invalidation service
# Protocol: [4-byte header_len][header_json][4-byte payload_len][payload][32-byte hmac]

_secret_env = os.environ.get('SESSION_SECRET')
if not _secret_env:
    raise RuntimeError(
        "SESSION_SECRET environment variable must be set to a strong, unique value. "
        "Refusing to start with a default/predictable key."
    )
SECRET_KEY = _secret_env.encode('utf-8')
MAX_TOKEN_SIZE = 8192
ALLOWED_ACTIONS = frozenset(['invalidate', 'refresh', 'query', 'ping'])

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison to prevent side-channel attacks."""
    return hmac.compare_digest(a, b)

def compute_hmac(data: bytes) -> bytes:
    """Compute HMAC-SHA256 over the given data."""
    return hmac.new(SECRET_KEY, data, hashlib.sha256).digest()

def validate_header(header: Dict[str, Any]) -> bool:
    """Validate header fields for safety."""
    required_fields = {'version', 'action', 'timestamp'}
    if not required_fields.issubset(header.keys()):
        return False
    if header.get('version') not in (1, 2):
        return False
    if header.get('action') not in ALLOWED_ACTIONS:
        return False
    ts = header.get('timestamp')
    if not isinstance(ts, (int, float)) or ts < 0:
        return False
    return True

def sanitize_cache_key(key: str) -> str:
    """Sanitize cache keys to prevent injection."""
    if not isinstance(key, str):
        raise ValueError("Cache key must be a string")
    if len(key) > 256:
        raise ValueError("Cache key too long")
    if not re.match(r'^[a-zA-Z0-9:._\-]+$', key):
        raise ValueError("Cache key contains invalid characters")
    return key

def parse_token(token_bytes: bytes) -> Optional[Tuple[Dict, bytes]]:
    """Parse and verify a session token.

    Token format:
    [4-byte header_len (big-endian unsigned)]
    [header_json bytes]
    [4-byte payload_len (big-endian unsigned)]
    [payload bytes]
    [32-byte HMAC-SHA256]

    Security: HMAC covers header_len + header + payload_len + payload
    """
    if not isinstance(token_bytes, bytes):
        return None

    if len(token_bytes) > MAX_TOKEN_SIZE:
        return None

    if len(token_bytes) < 40:  # minimum: 4 + 0 + 4 + 0 + 32
        return None

    # Extract HMAC (last 32 bytes)
    received_hmac = token_bytes[-32:]
    signed_data = token_bytes[:-32]

    # Verify HMAC first (verify-then-parse pattern)
    expected_hmac = compute_hmac(signed_data)
    if not constant_time_compare(received_hmac, expected_hmac):
        return None

    # HMAC verified - now parse the authenticated data
    offset = 0

    # Parse header length (unsigned 4-byte big-endian)
    header_len = struct.unpack('>I', signed_data[offset:offset+4])[0]
    offset += 4

    if header_len > 2048:
        return None

    if offset + header_len > len(signed_data):
        return None

    header_bytes = signed_data[offset:offset+header_len]
    offset += header_len

    # Parse payload length (unsigned 4-byte big-endian)
    payload_len = struct.unpack('>I', signed_data[offset:offset+4])[0]
    offset += 4

    # Validate payload length within bounds
    if payload_len > 4096:
        return None

    if offset + payload_len > len(signed_data):
        return None

    payload_bytes = signed_data[offset:offset+payload_len]

    # Parse and validate header
    try:
        header = json.loads(header_bytes.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None

    if not validate_header(header):
        return None

    return (header, payload_bytes)

def process_cache_command(token_b64: str) -> Dict[str, Any]:
    """Process an authenticated cache invalidation command."""
    try:
        token_bytes = base64.b64decode(token_b64)
    except Exception:
        return {'status': 'error', 'message': 'Invalid token encoding'}

    result = parse_token(token_bytes)
    if result is None:
        return {'status': 'error', 'message': 'Token verification failed'}

    header, payload = result
    action = header['action']

    if action == 'invalidate':
        return _handle_invalidate(payload, header)
    elif action == 'refresh':
        return _handle_refresh(payload, header)
    elif action == 'query':
        return _handle_query(payload, header)
    elif action == 'ping':
        return {'status': 'ok', 'action': 'pong'}

    return {'status': 'error', 'message': 'Unknown action'}

def _handle_invalidate(payload: bytes, header: Dict) -> Dict[str, Any]:
    """Handle cache invalidation - deserializes payload for batch operations."""
    if header.get('version') == 2:
        # Version 2 supports batch operations via JSON payload
        try:
            batch_data = json.loads(payload.decode('utf-8'))
            if not isinstance(batch_data, dict):
                return {'status': 'error', 'message': 'Invalid batch format'}
            keys = batch_data.get('keys', [])
            if not isinstance(keys, list) or len(keys) > 100:
                return {'status': 'error', 'message': 'Invalid keys list'}
            sanitized_keys = [sanitize_cache_key(k) for k in keys]
            return {'status': 'ok', 'invalidated': len(sanitized_keys)}
        except (json.JSONDecodeError, UnicodeDecodeError, ValueError) as e:
            return {'status': 'error', 'message': str(e)}
    else:
        # Version 1: single key in payload
        try:
            key = sanitize_cache_key(payload.decode('utf-8'))
            return {'status': 'ok', 'invalidated': 1, 'key': key}
        except (UnicodeDecodeError, ValueError) as e:
            return {'status': 'error', 'message': str(e)}

def _handle_refresh(payload: bytes, header: Dict) -> Dict[str, Any]:
    """Handle cache refresh command."""
    try:
        key = sanitize_cache_key(payload.decode('utf-8'))
        return {'status': 'ok', 'refreshed': key}
    except (UnicodeDecodeError, ValueError) as e:
        return {'status': 'error', 'message': str(e)}

def _handle_query(payload: bytes, header: Dict) -> Dict[str, Any]:
    """Handle cache query command."""
    try:
        key = sanitize_cache_key(payload.decode('utf-8'))
        return {'status': 'ok', 'key': key, 'exists': True}
    except (UnicodeDecodeError, ValueError) as e:
        return {'status': 'error', 'message': str(e)}
